import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"切割","description":"","frontmatter":{"title":"切割"},"headers":[],"relativePath":"zh/cutting/intro.md","filePath":"zh/cutting/intro.md","lastUpdated":1789241305000}'),n={name:"zh/cutting/intro.md"};function o(i,t,h,c,l,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="切割" tabindex="-1">切割 <a class="header-anchor" href="#切割" aria-label="Permalink to &quot;切割&quot;">​</a></h1><p>切割是把原石转化为宝石的工艺与科学。本模块讲解三类主切割路线—— 刻面切割（faceting）、蛋面/雕刻（cabochon &amp; carving），以及花式切工的 历史与参数。路线选择还要综合透明度、包裹体、耐久性、光学效应与原石形状。</p><h2 id="切割主题" tabindex="-1">切割主题 <a class="header-anchor" href="#切割主题" aria-label="Permalink to &quot;切割主题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>概述</th></tr></thead><tbody><tr><td><a href="./rough-planning.html">原石规划与定向</a></td><td>切工不是从“选择一个漂亮轮廓”开始，而是先读懂原石：观察体色分布、裂隙、 包裹体、透明度、晶体方向与潜在光学效应，再在重量保留、视觉效果和耐久性之间 做出取舍。规划图应记录台面方向、预计轮廓、主要风险和允许的损耗范围。</td></tr><tr><td><a href="./brilliant-cut.html">圆明亮式切工</a></td><td>现代最经典的钻石切工，标准 57–58 刻面，诞生于 1919 年 Marcel Tolkowsky 的比例理论。台面、冠部、腰棱、亭部比例配合 最大化内部全反射与火彩。</td></tr><tr><td><a href="./fancy-cuts.html">花式切工</a></td><td>非圆明亮式的异形、阶梯式与改良明亮式切工通常归入花式切工——公主方、祖母绿切、梨形、 椭圆形、马眼形、心形、祖母绿阶梯切等。每种依原石形状、内含物 位置与审美偏好而选。</td></tr><tr><td><a href="./cabochon-and-carving.html">蛋面与雕刻</a></td><td>当透明度、包裹体、耐久性或特殊光学效应更适合弧面时，宝石常采用蛋面 （凸圆打磨）或雕刻；这不是对所有材料的绝对限制。蛋面可突出星光、 猫眼、月光等现象，玉石与玛瑙也常见雕刻路线。</td></tr></tbody></table>',4)])])}const m=a(n,[["render",o]]);export{f as __pageData,m as default};
